// ------------------------------------------------------------
// Helper function to calculate next due date based on frequency rule
// Returns null until the user has actually set a "last completed" date
// (i.e. after system initialization / first completion), instead of
// defaulting to an arbitrary 3-months-from-now placeholder.
// ------------------------------------------------------------
const calculateNextDue = (lastCompleted, frequencyRule) => {
  if (!lastCompleted) {
    return null;
  }
  const lastDate = new Date(lastCompleted);
  let monthsToAdd = 12; // default annual

  // Parse frequency rule
  const rule = frequencyRule.toLowerCase();
  if (rule.includes('annually') || rule.includes('year') || rule.includes('≤15 months')) {
    monthsToAdd = 12;
  } else if (rule.includes('biennial') || rule.includes('2 year') || rule.includes('≤39 months') || rule.includes('every 3 years')) {
    monthsToAdd = 24;
  } else if (rule.includes('quarterly') || rule.includes('4x/year')) {
    monthsToAdd = 3;
  } else if (rule.includes('semi-annual') || rule.includes('2x/year')) {
    monthsToAdd = 6;
  } else if (rule.includes('≤7.5 months')) {
    monthsToAdd = 7.5;
  } else if (rule.includes('≤63 months') || rule.includes('5 years')) {
    monthsToAdd = 60;
  } else if (rule.includes('≤4 years')) {
    monthsToAdd = 48;
  } else if (rule.includes('≤7 years')) {
    monthsToAdd = 84;
  } else if (rule.includes('≤2.5 months')) {
    monthsToAdd = 2.5;
  }
  const nextDate = new Date(lastDate);
  nextDate.setMonth(nextDate.getMonth() + monthsToAdd);
  return nextDate.toISOString().split('T')[0];
};

// ------------------------------------------------------------
// Helper to determine status based on due date
// '' (blank)   -> no due date set yet
// 'compliant'  -> outside the 3-month action window, on schedule
// 'due'        -> within 3 months (90 days) of the deadline
// 'past due'   -> deadline has passed
// ------------------------------------------------------------
const getStatusFromDue = dueDate => {
  if (!dueDate) return '';
  const now = new Date();
  const due = new Date(dueDate);
  const daysUntilDue = Math.ceil((due - now) / (1000 * 60 * 60 * 24));
  if (daysUntilDue < 0) return 'past due';
  if (daysUntilDue <= 90) return 'due';
  return 'compliant';
};

// Format date for display
const formatDate = dateString => {
  if (!dateString) return 'Not set';
  const date = new Date(dateString);
  return date.toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric'
  });
};

